import type { ReactiveController, ReactiveControllerHost } from "lit";

type Cleanup = () => void;
type Listener = () => void;

/** Keeps existing synchronous page controllers alive while Solid owns their DOM. */
export class ControllerHost implements ReactiveControllerHost {
  private readonly controllers = new Set<ReactiveController>();
  private readonly listeners = new Set<Listener>();
  private pendingUpdate: Promise<boolean> | null = null;
  isConnected = false;

  addController(controller: ReactiveController): void {
    this.controllers.add(controller);
    if (this.isConnected) {
      controller.hostConnected?.();
    }
  }

  removeController(controller: ReactiveController): void {
    this.controllers.delete(controller);
  }

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  requestUpdate(): void {
    if (!this.pendingUpdate) {
      const pending: Promise<boolean> = Promise.resolve().then(() => {
        if (this.pendingUpdate === pending) {
          this.performUpdate();
        }
        return true;
      });
      this.pendingUpdate = pending;
    }
  }

  /** Frame owners can publish before paint without a second queued notification. */
  performUpdate(): void {
    if (!this.isConnected) {
      this.pendingUpdate = null;
      return;
    }
    // Controller publications belong to this update; listeners read their new facts below.
    this.pendingUpdate ??= Promise.resolve(true);
    try {
      for (const controller of this.controllers) {
        controller.hostUpdate?.();
      }
    } finally {
      this.pendingUpdate = null;
    }
    for (const listener of this.listeners) {
      listener();
    }
  }

  get updateComplete(): Promise<boolean> {
    return this.pendingUpdate ?? Promise.resolve(true);
  }

  connect(): void {
    this.isConnected = true;
    for (const controller of this.controllers) {
      controller.hostConnected?.();
    }
    this.requestUpdate();
  }

  disconnect(): void {
    this.pendingUpdate = null;
    this.isConnected = false;
    for (const controller of this.controllers) {
      controller.hostDisconnected?.();
    }
  }
}

/** State stays synchronous; the setter only publishes a rendering invalidation. */
export function viewState() {
  return (prototype: ControllerHost, key: string): void => {
    const values = new WeakMap<ControllerHost, unknown>();
    Object.defineProperty(prototype, key, {
      configurable: true,
      get(this: ControllerHost) {
        return values.get(this);
      },
      set(this: ControllerHost, value: unknown) {
        if (!Object.is(values.get(this), value)) {
          values.set(this, value);
          this.requestUpdate();
        }
      },
    });
  };
}

type SourceEntry<T> = {
  readonly getSource: () => T | null | undefined;
  readonly connect: (source: T) => Cleanup | undefined;
  readonly invalidateOnConnect: boolean;
  source: T | undefined;
  cleanup: Cleanup | undefined;
  generation: number;
  frame: number | undefined;
};

/**
 * Owns subscriptions whose sources can arrive or change after connection.
 * Source identity is checked before every render and all cleanup follows the
 * host lifecycle, so consumers do not need connected/updated retry loops.
 */
export class SubscriptionsController implements ReactiveController {
  private readonly entries: SourceEntry<unknown>[] = [];
  private connected = false;

  constructor(private readonly host: ReactiveControllerHost) {
    host.addController(this);
  }

  watchStore<T extends { subscribe: (notify: () => void) => Cleanup }>(
    getSource: () => T | null | undefined,
    synchronize?: (source: T) => void,
    commitInFrame?: () => void,
  ): this {
    return this.watch(
      getSource,
      (source, notify) => source.subscribe(notify),
      synchronize,
      commitInFrame,
    );
  }

  watch<T>(
    getSource: () => T | null | undefined,
    subscribe: (source: T, notify: () => void) => Cleanup,
    synchronize?: (source: T) => void,
    commitInFrame?: () => void,
  ): this {
    return this.addEntry(
      getSource,
      (source, entry) => {
        const generation = entry.generation;
        const notify = () => {
          if (
            !this.connected ||
            entry.generation !== generation ||
            !Object.is(entry.source, source)
          ) {
            return;
          }
          synchronize?.(source);
          if (
            !commitInFrame ||
            globalThis.document?.visibilityState === "hidden" ||
            typeof globalThis.requestAnimationFrame !== "function"
          ) {
            this.host.requestUpdate();
          } else if (entry.frame === undefined) {
            entry.frame = globalThis.requestAnimationFrame(() => {
              entry.frame = undefined;
              if (
                !this.connected ||
                entry.generation !== generation ||
                !Object.is(entry.getSource(), source)
              ) {
                return;
              }
              this.host.requestUpdate();
              // Commit bindings in the same frame, before Lit's queued microtask.
              commitInFrame();
            });
          }
        };
        const cleanup = subscribe(source, notify);
        // Make cleanup visible before synchronization in case initial state
        // projection throws after the external listener is already registered.
        entry.cleanup = cleanup;
        synchronize?.(source);
        return cleanup;
      },
      true,
    );
  }

  effect<T>(
    getSource: () => T | null | undefined,
    connect: (source: T) => Cleanup | undefined,
  ): this {
    return this.addEntry(getSource, (source) => connect(source), false);
  }

  hostConnected(): void {
    this.connected = true;
    this.refresh(true);
  }

  hostUpdate(): void {
    if (this.connected) {
      this.refresh(false);
    }
  }

  clear(): void {
    for (const entry of this.entries) {
      this.disconnectEntry(entry);
    }
  }

  hostDisconnected(): void {
    this.connected = false;
    this.clear();
  }

  private addEntry<T>(
    getSource: () => T | null | undefined,
    connect: (source: T, entry: SourceEntry<T>) => Cleanup | undefined,
    invalidateOnConnect: boolean,
  ): this {
    const entry: SourceEntry<T> = {
      getSource,
      connect: (source) => connect(source, entry),
      invalidateOnConnect,
      source: undefined,
      cleanup: undefined,
      generation: 0,
      frame: undefined,
    };
    this.entries.push(entry as SourceEntry<unknown>);
    if (this.connected) {
      this.refreshEntry(entry, invalidateOnConnect);
    }
    return this;
  }

  private refresh(requestUpdate: boolean): void {
    for (const entry of this.entries) {
      this.refreshEntry(entry, requestUpdate && entry.invalidateOnConnect);
    }
  }

  private refreshEntry<T>(entry: SourceEntry<T>, requestUpdate: boolean): void {
    const source = entry.getSource() ?? undefined;
    if (Object.is(entry.source, source)) {
      return;
    }
    this.disconnectEntry(entry);
    if (source === undefined) {
      return;
    }
    entry.source = source;
    entry.generation += 1;
    try {
      entry.cleanup = entry.connect(source);
    } catch (error) {
      this.disconnectEntry(entry);
      throw error;
    }
    if (requestUpdate) {
      this.host.requestUpdate();
    }
  }

  private disconnectEntry<T>(entry: SourceEntry<T>): void {
    entry.generation += 1;
    if (entry.frame !== undefined) {
      globalThis.cancelAnimationFrame(entry.frame);
      entry.frame = undefined;
    }
    entry.source = undefined;
    const cleanup = entry.cleanup;
    entry.cleanup = undefined;
    if (!cleanup) {
      return;
    }
    try {
      cleanup();
    } catch (error) {
      console.error("[openclaw] subscription cleanup failed", error);
    }
  }
}
